/*
 * MAY WE EMAIL THIS ACCOUNT ABOUT A MESSAGE? (TASK-L187 §2)
 *
 * THE ONE GATE every notification passes — the product's `canEmail` (L54). It
 * answers false when the account has asked not to be emailed (`emailOptOutAt`)
 * OR has no address. A sender that read `_User` itself would be a second
 * spelling of this rule, and tools/check-opt-out.mjs fails on any cloud
 * component that places a Send Email node without this gate in front of it.
 *
 * SIGN-IN LINKS NEVER PASS THROUGH HERE. The backend sends those itself, and the
 * control that reverses an opt-out is behind the login (L125's lockout).
 */
if (Inputs.userId !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      const users = userId ? await Noodl.Records.query('_User', { objectId: { equalTo: userId } }, { limit: 2, plain: true }) : [];
      if (users.length > 1) throw new Error('two accounts for one id');
      const u = users[0];
      const to = u && typeof u.email === 'string' && /@/.test(u.email) ? u.email : '';
      const optedOut = Boolean(u && u.emailOptOutAt);
      Outputs.to = to;
      Outputs.may = Boolean(u) && !optedOut && to !== '';
      Outputs.done();
    } catch (e) {
      Outputs.may = false;
      console.error('[dbt:May email] ' + String((e && e.message) || e) + ' user=' + String(Inputs.userId || '-'));
      Outputs.done();
    }
  })();
}
